SELECT table_name,engine FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('id_hr_session','id_hr_grant','ai_hr_source_authorization','ai_hr_feedback','ai_hr_run_event','ai_hr_context_version','ai_hr_batch_limits','pf_private_file','pf_private_reference') ORDER BY table_name;
SELECT table_name,index_name,column_name,seq_in_index FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name IN ('id_hr_session','id_hr_grant','ai_hr_source_authorization','ai_hr_feedback','ai_hr_run_event','ai_hr_context_version','ai_hr_batch_limits','pf_private_file','pf_private_reference') ORDER BY table_name,index_name,seq_in_index;
